p='../../src/discovery/mod.rs'
cut=None
for i,l in enumerate(open(p),1):
    if '#[cfg(test)]' in l: cut=i; break
n=0
for i,l in enumerate(open(p),1):
    if cut and i>=cut: break
    if '.unwrap()' in l and not l.strip().startswith('//'):
        n+=l.count('.unwrap()'); print('site:', i, l.strip()[:90])
print('non-test .unwrap() calls in src/discovery/mod.rs:', n)
